def solve(s: str) -> int:
    if not s: return 0
    max_len = 1
    def expand(l, r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return r - l - 1
    for i in range(len(s)):
        max_len = max(max_len, expand(i, i), expand(i, i + 1))
    return max_len

